      var tz = ''; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) {}
      var lang = (navigator.language || '').toLowerCase();
      var india = /Kolkata|Calcutta/.test(tz) || /-in$/.test(lang) || /^(hi|ta|te|bn|mr|kn|ml|gu|pa)/.test(lang);
      var EURO = /^Europe\/(Paris|Berlin|Madrid|Rome|Amsterdam|Brussels|Vienna|Dublin|Lisbon|Athens|Helsinki|Luxembourg|Bratislava|Ljubljana|Tallinn|Riga|Vilnius|Valletta|Nicosia|Zagreb)$/;
      if (!cfg.paypalMe && !india) return;  // UPI only works for people with an Indian bank account
