        var INR = { INR: 1, USD: 88, EUR: 102, GBP: 117, AUD: 58, CAD: 63 };  // rough rates, rounded, for the UPI amount
        if (method === 'upi') return 'upi://pay?pa=' + encodeURIComponent(cfg.upiId).replace('%40', '@') + '&pn=' + encodeURIComponent(cfg.upiName || 'Blog Digest') + '&am=' + (cur === 'INR' ? amt : Math.round(amt * INR[cur] / 10) * 10) + '&cu=INR&tn=' + encodeURIComponent('Coffee for Blog Digest');
        var c = cur === 'INR' ? 'USD' : cur, a = cur === 'INR' ? (amt >= 200 ? 5 : 3) : amt;
