            '<div class="bd-tip-cup">☕</div><h3>Buy me a coffee</h3><p>Every guide here is researched and sourced, and every tool runs privately on your device, all free: no paywalls, no sign-ups. If something here saved you time or money, a small tip keeps it going.</p>' +
            '<div class="bd-tip-amts" style="grid-template-columns:repeat(' + AMT.length + ',1fr) 1.3fr">' + AMT.map(function (v, i) { return '<button type="button" data-v="' + v + '"' + (i === 1 ? ' class="bd-on"' : '') + '>' + SYM[cur] + v + '</button>'; }).join('') +
            '<label class="bd-tip-custom">' + SYM[cur] + '<input type="number" min="1" step="1" inputmode="numeric" placeholder="Any" aria-label="Custom amount"/></label></div>' +
            '<div class="bd-tip-pay">' + (cfg.upiId && cur === 'INR' ? '<a class="bd-tip-upi" data-m="upi" href="#">Pay with UPI (GPay, PhonePe, Paytm)</a>' : '') +
            (cfg.paypalMe ? '<a class="bd-tip-pp" data-m="pp" href="#" target="_blank" rel="noopener">Pay with PayPal or card</a>' : '') +
            (cfg.upiId && cur !== 'INR' ? '<a class="bd-tip-upi bd-tip-alt" data-m="upi" href="#">In India? Pay with UPI</a>' : '') + '</div>' +
            '<div class="bd-tip-qr" hidden><canvas width="220" height="220"></canvas><small>Scan with any UPI app</small></div>' +
            '<small class="bd-tip-fine">Payments go through ' + (cfg.paypalMe && cfg.upiId ? 'PayPal or your UPI app' : cfg.paypalMe ? 'PayPal' : 'your UPI app') + '. Blog Digest never sees your card or bank details.</small></div>');
          document.body.appendChild(sheet);
          var amt = AMT[1], box = sheet.querySelector('.bd-tip-box'), custom = sheet.querySelector('.bd-tip-custom input');
          sheet.addEventListener('click', function (e) { if (e.target === sheet || e.target.closest('.bd-tip-x')) sheet.classList.remove('bd-open'); });
