              e.preventDefault(); var q = sheet.querySelector('.bd-tip-qr'); q.hidden = false;
              var draw = function () { qrcode.stringToBytes = qrcode.stringToBytesFuncs['UTF-8']; var c = qrcode(0, 'M'); c.addData(url, 'Byte'); c.make(); var n = c.getModuleCount(), cv = q.querySelector('canvas'), s = Math.floor(220 / (n + 8)), x = cv.getContext('2d');
                x.fillStyle = '#fff'; x.fillRect(0, 0, 220, 220); x.fillStyle = '#15171d'; var o = Math.floor((220 - n * s) / 2); for (var r = 0; r < n; r++) for (var k = 0; k < n; k++) if (c.isDark(r, k)) x.fillRect(o + k * s, o + r * s, s, s); };
              if (window.qrcode) draw(); else { var sc = document.createElement('script'); sc.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js'; sc.crossOrigin = 'anonymous';
                sc.integrity = 'sha384-mZT2gIty7ZDdOGkxfP6joZcYdMW1Jvj9dRlfpTmaJAKKXTqzygtB22k7FLe+KZC1'; sc.onload = draw; document.head.appendChild(sc); }
