            }
            a.href = url;
            setTimeout(function () { box.innerHTML = '<div class="bd-tip-cup">❤️</div><h3>Thank you!</h3><p>That really helps keep Blog Digest free for everyone.</p>'; setTimeout(function () { sheet.classList.remove('bd-open'); }, 2600); }, 600);
          });
        }
        requestAnimationFrame(function () { sheet.classList.add('bd-open'); });
      };
      var cta = function (cls, title, text) {
        var c = el('aside', 'bd-tip-card ' + (cls || ''), '<span class="bd-tip-mini"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 8h1a4 4 0 0 1 0 8h-1"/><path d="M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"/><path class="bd-steam" d="M7 2v2M11 2v2M15 2v2"/><path d="M10 16.2c-1.6-1-2.6-1.9-2.6-3a1.3 1.3 0 0 1 2.6-.3 1.3 1.3 0 0 1 2.6.3c0 1.1-1 2-2.6 3Z" fill="currentColor" stroke="none"/></svg></span><span><b>' + title + '</b><small>' + text + '</small></span>' +
          '<span class="bd-tip-quick">' + AMT.map(function (v) { return '<button type="button" data-v="' + v + '">' + SYM[cur] + v + '</button>'; }).join('') + '<button type="button" class="bd-tip-go">Buy me a coffee</button></span>');
        c.addEventListener('click', function (e) { if (e.target.closest('button')) open(cls); }); return c;
      };
      // 1. End of every article, just before the related reading
      if (isPost && body) {
        var anchor = body.querySelector('.seo-related') || Array.prototype.filter.call(body.querySelectorAll('h2'), function (h) { return /^Related Guides$/i.test(h.textContent.trim()); })[0] || document.querySelector('.bd-share-wrap');
        if (anchor && !body.querySelector('.bd-tip-card')) anchor.parentNode.insertBefore(cta('bd-tip-post', 'Found this useful?', 'Blog Digest is free with no paywalls. A coffee keeps the guides and tools coming.'), anchor);
      }
      // 2. Straight after someone uses a tool (a download, copy or convert), once a week at most
      document.addEventListener('click', function (e) {
        var b = e.target.closest('.bd-calc button, .bd-calc a[download]'); if (!b || askedRecently() || document.querySelector('.bd-tip-toast')) return;
        if (!/download|copy|convert|save|split|merge|sign|export|calendar/i.test(b.textContent)) return;
        setTimeout(function () {
          var t = el('div', 'bd-tip-toast', '<span>☕</span><p><b>Glad that worked!</b> This tool is free and private. If it saved you time, you can buy me a coffee.</p><button type="button" class="bd-tip-yes">Tip ' + SYM[cur] + AMT[0] + '+</button><button type="button" class="bd-tip-no" aria-label="No thanks">×</button>');
          document.body.appendChild(t); store('bd-tip-ask', Date.now()); requestAnimationFrame(function () { t.classList.add('bd-show'); });
          t.querySelector('.bd-tip-yes').onclick = function () { t.remove(); open('tool'); };
          t.querySelector('.bd-tip-no').onclick = function () { t.remove(); };
          setTimeout(function () { if (t.parentNode) t.remove(); }, 14000);
        }, 1400);
      }, true);
      // 3. Tools page, menu and footer
      if (/^\/p\/free-(tools|calculators)\.html$/.test(location.pathname)) { var hub = document.getElementById('bd-hub'); if (hub) hub.appendChild(cta('bd-tip-hub', 'Keep these tools free', 'No accounts, no limits, and your files never leave your device. A coffee helps pay for the time they take to build.')); }
      document.querySelectorAll('.bd-pn-tools').forEach(function (t) { var a = el('a', '', '<i>☕</i><span><b>Buy me a coffee</b><small>Support Blog Digest</small></span>'); a.href = '#'; a.onclick = function (e) { e.preventDefault(); open('menu'); }; t.appendChild(a); });
      // 4. A coffee-cup-with-heart button in the header, on every page
      var hdr = document.querySelector('.bd-tools');
      if (hdr && !hdr.querySelector('.bd-tipbtn')) { var hb = el('button', 'bd-tipbtn', '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 8h1a4 4 0 0 1 0 8h-1"/><path d="M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"/><path class="bd-steam" d="M7 2v2M11 2v2M15 2v2"/><path d="M10 16.2c-1.6-1-2.6-1.9-2.6-3a1.3 1.3 0 0 1 2.6-.3 1.3 1.3 0 0 1 2.6.3c0 1.1-1 2-2.6 3Z" fill="currentColor" stroke="none"/></svg><span>Support</span>'); hb.type = 'button';
        hb.setAttribute('aria-label', 'Buy me a coffee'); hb.title = 'Buy me a coffee'; hb.onclick = function () { open('header'); };
        var tl = hdr.querySelector('.bd-toolslink'); hdr.insertBefore(hb, tl ? tl.nextSibling : hdr.firstChild); }
    });

    // Follow: a "Get new articles" card at the end of articles, a one-time invitation after half an article, and a
    // row in the footer. Nothing appears until follow.json has at least one channel.
    withFollow(function (cfg) {
      var buttons = followButtons(cfg); if (!buttons) return;
      loadPush(cfg);
      var pf = document.querySelector('.item-post .post-footer');
      if (isPost && pf && !document.querySelector('.bd-follow')) {
        var card = el('aside', 'bd-follow', '<div><b>Get new articles as they are published</b><p>One tap. No spam, and you can stop any time.</p></div><div class="bd-fbtns">' + buttons + '</div>');
        pf.parentNode.insertBefore(card, document.querySelector('.bd-pubnote') || pf); wireFollow(card);
        var seen = 0; try { seen = +localStorage.getItem('bd-follow-asked') || 0; } catch (e) {}
        var ab = document.querySelector('.item-post .post-body');
        if (ab && Date.now() - seen > 30 * 864e5) {
          var toast = el('div', 'bd-ftoast', '<button type="button" class="bd-ftoast-x" aria-label="Close">×</button><b>Enjoying this?</b><p>Get Blog Digest’s new articles as soon as they are out.</p><div class="bd-fbtns">' + buttons + '</div>');
          toast.setAttribute('role', 'dialog'); toast.setAttribute('aria-label', 'Follow Blog Digest');
          document.body.appendChild(toast); wireFollow(toast);
          var onT = function () {
            var r = ab.getBoundingClientRect();
            if (-r.top / Math.max(1, r.height - innerHeight) > .5) { toast.classList.add('bd-show'); removeEventListener('scroll', onT); }
          };
          var close = function () { toast.classList.remove('bd-show'); try { localStorage.setItem('bd-follow-asked', Date.now()); } catch (e) {} removeEventListener('scroll', onT); };
          toast.querySelector('.bd-ftoast-x').addEventListener('click', close);
          toast.querySelectorAll('.bd-fbtn').forEach(function (x) { x.addEventListener('click', function () { setTimeout(close, 1200); }); });
          addEventListener('scroll', onT, { passive: true });
        }
      }
      var fb = document.querySelector('.bd-foot-brand');
      if (fb && !fb.querySelector('.bd-ffoot')) { var row = el('div', 'bd-ffoot', '<b>Follow Blog Digest</b><div class="bd-fbtns">' + buttons + '</div>'); fb.appendChild(row); wireFollow(row); }
    });

    // Back to top + sticky header shadow.
    var top = el('button', '', ICONS.up); top.id = 'bd-top'; top.type = 'button'; top.setAttribute('aria-label', 'Back to top');
    top.addEventListener('click', function () { scrollTo({ top: 0, behavior: 'smooth' }); });
    document.body.appendChild(top);
    var onScroll = function () {
      top.classList.toggle('bd-show', scrollY > 700);
      if (header) header.classList.toggle('bd-scrolled', scrollY > 10);
    };
    addEventListener('scroll', onScroll, { passive: true }); onScroll();

    // Reveal on scroll, for elements below the fold only; everything shows after 3 seconds regardless.
    var targets = document.querySelectorAll('.index-post, #sidebar-wrapper .widget, .bd-topic, .seo-related, .blog-post-comments, .bd-closer');
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function (es) {
        es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('bd-in'); io.unobserve(e.target); } });
      }, { rootMargin: '0px 0px -40px 0px' });
